"use strict";
// Plain JavaScript: rows are built key by key, so inference sees nothing.
function Cursor(text) {
  this.text = text;
  this.pos = 0;
}
Cursor.prototype.remaining = function () {
  return this.text.length - this.pos;
};
function parseRows(text) {
  var lines = String(text).split("\n").filter(Boolean);
  var header = lines[0].split(",");
  var rows = [];
  for (var i = 1; i < lines.length; i++) {
    var cells = lines[i].split(",");
    var row = {};
    for (var j = 0; j < header.length; j++) row[header[j]] = cells[j];
    rows.push({ line: i, cells: row, width: cells.length });
  }
  return rows;
}
function cursor(text) {
  return new Cursor(text);
}
exports.parseRows = parseRows;
exports.cursor = cursor;
